1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResults = {
19	  results: unknown[];
20	};
21	
22	const sum = (amounts: number[]): number =>
23	  amounts.reduce((total, amount) => total + amount, 0);
24	
25	const PROCESSING_FEE = 5;
26	
27	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
28	// 115.00000000000001); snap to cent precision so only genuine fractions round up.
29	const roundUpInMHPCOsFavour = (amount: number): number =>
30	  Math.ceil(Number(amount.toFixed(6)));
31	
32	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	};
39	
40	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
41	
42	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
43	
44	const COMPONENT_BLOCK_SIZE = 3;
45	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
46	
47	const policyBasePremiumOf = (items: Item[]): number =>
48	  items.length === COMPONENT_BLOCK_SIZE
49	    ? COMPONENT_BLOCK_BASE_PREMIUM
50	    : sum(items.map(basePremiumOf));
51	
52	const quote = (step: QuoteStep): number => {
53	  const policyBasePremium = policyBasePremiumOf(step.items);
54	  const firstInsuranceSurcharge =
55	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
56	
57	  return roundUpInMHPCOsFavour(
58	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
59	  );
60	};
61	
62	export const runScenario = (scenario: Scenario): ScenarioResults => {
63	  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
64	};
