// Only exactly-3-alike components form a block, but no test yet distinguishes
// "3 alike" from "3 items", so the check is still on the whole item count.
// The tests for 4 runes and for 3 runes + 3 moonstones will force the grouping.
const formsOneComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE;

const policyBasePremiumOf = (items: Item[]): number =>
  formsOneComponentBlock(items)
    ? COMPONENT_BLOCK_BASE_PREMIUM
    : sum(items.map(basePremiumOf));

